/* ==UserStyle==
@name Lichess Catppuccin
@namespace github.com/catppuccin/userstyles/styles/lichess
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/lichess
@version 2026.11.01
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/lichess/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Alichess
@description Soothing pastel theme for Lichess
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]

@var select lastMoveColor "Last Move" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve", "red:Red*", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
@var select checkColor "Check Indicator" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve", "red:Red*", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
@var checkbox stylePieces "Style Pieces" 1
@var checkbox styleBoard "Style Board" 1
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("lichess.org") {
  :root:has(body[data-theme~="light"]) {
    #catppuccin(@lightFlavor);
  }
  :root:has(body[data-theme~="dark"]) {
    #catppuccin(@darkFlavor);
  }
  :root:has(body[data-theme~="system"]) {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    @lastMove: @catppuccin[@@flavor][@@lastMoveColor];
    @check: @catppuccin[@@flavor][@@checkColor];

    --c-bg-page: @crust;
    --c-body-gradient: @base;
    --c-bg: @mantle;
    --c-bg-box: @base;
    --c-bg-high: @base;
    --c-bg-opaque: @mantle;
    --c-page-input: @mantle;
    --c-bg-input: @mantle;
    --c-bg-mid: @surface0;
    --c-bg-variation: @surface0;
    --c-bg-zebra: @surface0;
    --c-bg-low: @surface1;
    --c-bg-popup: @surface0;
    --c-bg-header-dropdown: @surface0;
    --c-bg-zebra2: @surface1;
    --c-pool-button: fade(@surface0, 66%);
    --c-metal-top: @surface0;
    --c-metal-bottom: @surface0;
    --c-metal-top-hover: @surface1;
    --c-metal-bottom-hover: @surface1;
    --c-page-mask: fade(@crust, 60%);

    --c-font: @text;
    --c-font-clear: @text;
    --c-font-clearer: @text;
    --c-font-dim: @subtext0;
    --c-font-dimmer: @overlay0;
    --c-font-page: @subtext1;
    --c-font-shadow: transparent;
    --c-header-dropdown: @text;
    --c-shade: @overlay0;
    --c-dark: @surface1;
    --c-dimmer: @crust;
    --c-clearer: @text;
    --c-over: @crust;
    --c-paper: @rosewater;

    --c-border: @surface1;
    --c-border-page: @surface0;
    --c-border-tour: fade(@surface0, 50%);
    --c-border-light: @overlay0;

    --c-primary: @accent;
    --c-primary-dim: darken(@accent, 8%);
    --c-primary-clear: lighten(@accent, 8%);
    --c-link: @blue;
    --c-link-dim: darken(@blue, 8%);
    --c-link-clear: lighten(@blue, 8%);
    --c-link-hover: @sapphire;
    --c-secondary: @green;
    --c-secondary-dim: darken(@green, 10%);
    --c-secondary-dimmer: darken(@green, 20%);
    --c-accent: @accent;
    --c-accent-dim: darken(@accent, 10%);
    --c-accent-clear: lighten(@accent, 8%);
    --c-accent-faint: fade(@accent, 40%);
    --c-accent-glass: fade(@accent, 20%);
    --c-accent-cloud: fade(@accent, 50%);
    --c-brag: @accent;
    --c-brag-hover: lighten(@accent, 8%);
    --c-contours: @accent;
    --c-fancy: @pink;
    --c-clas: @mauve;
    --c-future: @lavender;
    --c-dasher: @green;
    --c-dasher-light: fade(@green, 40%);
    --c-bot: @pink;
    --c-good: @green;
    --c-warn: @yellow;
    --c-bad: @red;
    --c-error: @red;
    --c-live: @red;
    --c-racer-boost: fade(@yellow, 70%);
    --c-marathon: @teal;
    --c-tutor-bg: fade(@green, 20%);
    --c-chat-host-bg: fade(@green, 25%);
    --c-chat-mention-bg: fade(@yellow, 25%);

    --c-inaccuracy: @sky;
    --c-mistake: @yellow;
    --c-blunder: @red;
    --c-good-move: @green;
    --c-brilliant: @teal;
    --c-interesting: @pink;
    --c-mv-branch-white: @text;
    --c-mv-branch-black: @crust;

    --c-patron-1: @green;
    --c-patron-2: @teal;
    --c-patron-3: @sky;
    --c-patron-4: @sapphire;
    --c-patron-5: @blue;
    --c-patron-6: @lavender;
    --c-patron-7: @mauve;
    --c-patron-8: @pink;
    --c-patron-9: @red;
    --c-patron-10: @peach;

    /* Lobby logo overlay: the path is copied from lila's public/images/logo.svg, so it goes stale if upstream redraws the logo. */
    .lobby__app__content {
      @svg: escape(
        '<svg viewBox="-2 -2 54 54" xmlns="http://www.w3.org/2000/svg"><path fill="@{surface0}" stroke="@{surface0}" stroke-linejoin="round" d="M38.956.5c-3.53.418-6.452.902-9.286 2.984C5.534 1.786-.692 18.533.68 29.364 3.493 50.214 31.918 55.785 41.329 41.7c-7.444 7.696-19.276 8.752-28.323 3.084S-.506 27.392 4.683 17.567C9.873 7.742 18.996 4.535 29.03 6.405c2.43-1.418 5.225-3.22 7.655-3.187l-1.694 4.86 12.752 21.37c-.439 5.654-5.459 6.112-5.459 6.112-.574-1.47-1.634-2.942-4.842-6.036S19.977 19.347 21.654 13.317c-2.001 6.967 10.311 14.152 14.04 17.663 3.73 3.51 5.426 6.04 5.795 6.756 0 0 9.392-2.504 7.838-8.927L37.4 7.171z"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}") !important;
    }

    .button:not(.disabled):hover {
      filter: none;
    }

    /* Chess Game */
    @light-cell: if(@flavor = latte, @surface0, @accent);
    @dark-cell: if(@flavor = latte, @accent, @surface0);
    & when (@styleBoard = 1) {
      /* Board */
      .is2d cg-board::before {
        @svg: escape(
          '<svg shape-rendering="crispEdges" viewBox="0 0 8 8" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"><g id="f"><g id="e"><g id="d"><g id="c"><path id="a" d="M0 0h1v1H0z" fill="@{light-cell}"/><use x="1" xlink:href="#a" y="1"/><path id="b" d="M0 1h1v1H0z" fill="@{dark-cell}"/><use x="1" xlink:href="#b" y="-1"/></g><use x="2" xlink:href="#c"/></g><use x="4" xlink:href="#d"/></g><use xlink:href="#e" y="2"/></g><use xlink:href="#f" y="4"/></svg>'
        );
        background-image: url("data:image/svg+xml,@{svg}") !important;
      }

      /* File and Rank Coords */
      .orientation-white .files coord:nth-child(2n+1),
      .orientation-white .ranks coord:nth-child(2n),
      .orientation-black .files coord:nth-child(2n),
      .orientation-black .ranks coord:nth-child(2n+1) {
        color: @light-cell;
      }
      .orientation-white .files coord:nth-child(2n),
      .orientation-white .ranks coord:nth-child(2n+1),
      .orientation-black .files coord:nth-child(2n+1),
      .orientation-black .ranks coord:nth-child(2n) {
        color: @dark-cell;
      }

      /* Squares */
      square {
        &.move-dest {
          background: radial-gradient(
            @overlay1 19%,
            rgba(0, 0, 0, 0) 20%
          );
        }

        &.selected {
          background: fade(@accent, 50%);
        }

        &.last-move {
          background-color: fade(@lastMove, 75%);
        }

        &.check {
          background: radial-gradient(
            ellipse at center,
            @check 0%,
            @check 25%,
            fade(@check, 0%) 89%,
            fade(@check, 0%) 100%
          );
        }

        /* Capture indicator */
        &.oc.move-dest {
          background: radial-gradient(
            transparent 0%,
            transparent 79%,
            fade(@overlay1, 50%) 80%
          );
        }
      }

      /* Analysis Arrows */
      svg.cg-shapes g {
        &[cgHash*="green"] {
          filter: @green-filter;
        }
        &[cgHash*="paleBlue"] {
          filter: @sky-filter;
        }
        &[cgHash*="red"] {
          filter: @red-filter;
        }
      }
    }
    & when (@stylePieces = 1) {
      @w-piece-fill: if(@flavor = latte, @mantle, @text);
      @b-piece-fill: if(@flavor = latte, @text, @mantle);
      @w-piece-stroke: if(@flavor = latte, @text, @mantle);
      @b-piece-stroke: if(@flavor = latte, @mantle, @text);

      .is2d .pawn {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><path d="M22.5 9c-2.21 0-4 1.79-4 4 0 .89.29 1.71.78 2.38C17.33 16.5 16 18.59 16 21c0 2.03.94 3.84 2.41 5.03-3 1.06-7.41 5.55-7.41 13.47h23c0-7.92-4.41-12.41-7.41-13.47 1.47-1.19 2.41-3 2.41-5.03 0-2.41-1.33-4.5-3.28-5.62.49-.67.78-1.49.78-2.38 0-2.21-1.79-4-4-4z" stroke="@{s}" fill="@{f}" stroke-width="1.5" stroke-linecap="round"/></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
      .is2d .bishop {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><g fill="none" fill-rule="evenodd" stroke="@{s}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><g fill="@{f}" stroke-linecap="butt"><path d="M9 36c3.39-.97 10.11.43 13.5-2 3.39 2.43 10.11 1.03 13.5 2 0 0 1.65.54 3 2-.68.97-1.65.99-3 .5-3.39-.97-10.11.46-13.5-1-3.39 1.46-10.11.03-13.5 1-1.354.49-2.323.47-3-.5 1.354-1.94 3-2 3-2z"/><path d="M15 32c2.5 2.5 12.5 2.5 15 0 .5-1.5 0-2 0-2 0-2.5-2.5-4-2.5-4 5.5-1.5 6-11.5-5-15.5-11 4-10.5 14-5 15.5 0 0-2.5 1.5-2.5 4 0 0-.5.5 0 2z"/><path d="M25 8a2.5 2.5 0 1 1-5 0 2.5 2.5 0 1 1 5 0z"/></g><path d="M17.5 26h10M15 30h15m-7.5-14.5v5M20 18h5" stroke="@{s}" stroke-linejoin="miter"/></g></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
      .is2d .knight {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><g fill="none" fill-rule="evenodd" stroke="@{s}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 10c10.5 1 16.5 8 16 29H15c0-9 10-6.5 8-21" fill="@{f}"/><path d="M24 18c.38 2.91-5.55 7.37-8 9-3 2-2.82 4.34-5 4-1.042-.94 1.41-3.04 0-3-1 0 .19 1.23-1 2-1 0-4.003 1-4-4 0-2 6-12 6-12s1.89-1.9 2-3.5c-.73-.994-.5-2-.5-3 1-1 3 2.5 3 2.5h2s.78-1.992 2.5-3c1 0 1 3 1 3" fill="@{f}"/><path d="M9.5 25.5a.5.5 0 1 1-1 0 .5.5 0 1 1 1 0m5.433-9.75a.5 1.5 30 1 1-.866-.5.5 1.5 30 1 1 .866.5" fill="@{f}" stroke="@{s}"/></g></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
      .is2d .rook {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><g fill-rule="evenodd" fill="@{f}" stroke="@{s}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M9 39h27v-3H9zm3.5-7 1.5-2.5h17l1.5 2.5zm-.5 4v-4h21v4z" stroke-linecap="butt"/><path d="M14 29.5v-13h17v13z" stroke-linecap="butt" stroke-linejoin="miter"/><path d="M14 16.5 11 14h23l-3 2.5zM11 14V9h4v2h5V9h5v2h5V9h4v5z" stroke-linecap="butt"/><path d="M12 35.5h21m-20-4h19m-18-2h17m-17-13h17M11 14h23" fill="none" stroke="@{s}" stroke-width="1" stroke-linejoin="miter"/></g></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
      .is2d .king {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><g fill="@{f}" fill-rule="evenodd" stroke="@{s}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22.5 11.63V6" stroke-linejoin="miter"/><path d="M22.5 25s4.5-7.5 3-10.5c0 0-1-2.5-3-2.5s-3 2.5-3 2.5c-1.5 3 3 10.5 3 10.5" fill="@{f}" stroke-linecap="butt" stroke-linejoin="miter"/><path d="M11.5 37c5.5 3.5 15.5 3.5 21 0v-7s9-4.5 6-10.5c-4-6.5-13.5-3.5-16 4V27v-3.5c-3.5-7.5-13-10.5-16-4-3 6 5 10 5 10z" fill="@{f}"/><path d="M20 8h5" stroke-linejoin="miter"/><path d="M11.5 30c5.5-3 15.5-3 21 0m-21 3.5c5.5-3 15.5-3 21 0m-21 3.5c5.5-3 15.5-3 21 0" stroke="@{s}"/></g></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
      .is2d .queen {
        #piece(@f, @s) {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" width="45" height="45"><g fill="@{f}" fill-rule="evenodd" stroke="@{s}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M8 12a2 2 0 1 1-4 0 2 2 0 1 1 4 0m16.5-4.5a2 2 0 1 1-4 0 2 2 0 1 1 4 0M41 12a2 2 0 1 1-4 0 2 2 0 1 1 4 0M16 8.5a2 2 0 1 1-4 0 2 2 0 1 1 4 0M33 9a2 2 0 1 1-4 0 2 2 0 1 1 4 0"/><path d="M9 26c8.5-1.5 21-1.5 27 0l2-12-7 11V11l-5.5 13.5-3-15-3 15-5.5-14V25L7 14z" stroke-linecap="butt"/><path d="M9 26c0 2 1.5 2 2.5 4 1 1.5 1 1 .5 3.5-1.5 1-1.5 2.5-1.5 2.5-1.5 1.5.5 2.5.5 2.5 6.5 1 16.5 1 23 0 0 0 1.5-1 0-2.5 0 0 .5-1.5-1-2.5-.5-2.5-.5-2 .5-3.5 1-2 2.5-2 2.5-4-8.5-1.5-18.5-1.5-27 0z" stroke-linecap="butt"/><path d="M11.5 30c3.5-1 18.5-1 22 0M12 33.5c6-1 15-1 21 0" fill="none"/></g></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}") !important;
        }
        &.black {
          #piece(@b-piece-fill, @b-piece-stroke);
        }
        &.white {
          #piece(@w-piece-fill, @w-piece-stroke);
        }
      }
    }
  }
}
